-- compare_fh.tsv: for each literal, how many rows of tf `fh <op> <literal>` keeps, the
-- sum of their id, and how many rows DuckDB cannot decide (the comparison raises a
-- conversion error: TRY gives NULL for a row whose fh is not NULL), for each of the six
-- comparison operators. The literal is the SQL text the test runs too (a folded bound is
-- written as the arithmetic), so the file holds DuckDB's reading of it. NULL rows are in
-- neither the kept rows nor their complement. Column fh of tf holds values near 2^53 unscaled and wide ones; the literals are DOUBLE.
COPY (
SELECT * FROM (
  SELECT 0 AS n, 'fh' AS col, '90071992547409.9375 * 1e0' AS lit,
    (SELECT count(*) FROM tf WHERE TRY(fh < 90071992547409.9375 * 1e0)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh < 90071992547409.9375 * 1e0)) AS lt_s, (SELECT count(*) FROM tf WHERE TRY(fh < 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tf WHERE TRY(fh <= 90071992547409.9375 * 1e0)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh <= 90071992547409.9375 * 1e0)) AS le_s, (SELECT count(*) FROM tf WHERE TRY(fh <= 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tf WHERE TRY(fh > 90071992547409.9375 * 1e0)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh > 90071992547409.9375 * 1e0)) AS gt_s, (SELECT count(*) FROM tf WHERE TRY(fh > 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tf WHERE TRY(fh >= 90071992547409.9375 * 1e0)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh >= 90071992547409.9375 * 1e0)) AS ge_s, (SELECT count(*) FROM tf WHERE TRY(fh >= 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tf WHERE TRY(fh = 90071992547409.9375 * 1e0)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh = 90071992547409.9375 * 1e0)) AS eq_s, (SELECT count(*) FROM tf WHERE TRY(fh = 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tf WHERE TRY(fh <> 90071992547409.9375 * 1e0)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh <> 90071992547409.9375 * 1e0)) AS ne_s, (SELECT count(*) FROM tf WHERE TRY(fh <> 90071992547409.9375 * 1e0) IS NULL AND fh IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 1 AS n, 'fh' AS col, '90071992547409.93 * 1e0' AS lit,
    (SELECT count(*) FROM tf WHERE TRY(fh < 90071992547409.93 * 1e0)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tf WHERE TRY(fh < 90071992547409.93 * 1e0)) AS lt_s, (SELECT count(*) FROM tf WHERE TRY(fh < 90071992547409.93 * 1e0) IS NULL AND fh IS NOT NULL) AS lt_e,
